            foreach(var v in gen.verts){if(v.color.a==0)continue;var point=camera.WorldToViewportPoint(text.transform.TransformPoint(v.position/text.pixelsPerUnit));minX=UnityEngine.Mathf.Min(minX,point.x);maxX=UnityEngine.Mathf.Max(maxX,point.x);minY=UnityEngine.Mathf.Min(minY,point.y);maxY=UnityEngine.Mathf.Max(maxY,point.y);}
            report.Append(MenuPath(text.transform)).Append('\t').Append(Q64(text.text)).Append('\t').Append(alpha).Append('\t').Append(gen.characterCountVisible).Append('\t').Append(text.text.Length).Append('\t').Append(minX).Append('\t').Append(maxX).Append('\t').Append(minY).Append('\t').Append(maxY).Append('\t').Append(text.fontSize).Append('\n');
        }System.IO.File.WriteAllText(System.IO.Path.Combine(root,"quest-hud-geometry.tsv"),report.ToString());
    }
    void QuestScroll(string end){QuestPrepare();var scroll=questPane.GetComponent<UnityEngine.UI.ScrollRect>();scroll.StopMovement();scroll.verticalNormalizedPosition=end=="top"?1:0;UnityEngine.Canvas.ForceUpdateCanvases();System.IO.File.WriteAllText(System.IO.Path.Combine(root,"quest-scroll-direct.txt"),end+"|"+scroll.verticalNormalizedPosition+"|"+scroll.content.anchoredPosition+"|"+scroll.content.rect+"|"+scroll.viewport.rect);}
    void QuestRestore(){for(int i=questUndo.Count-1;i>=0;i--){var u=questUndo[i];u.field.SetValue(u.owner,u.value);}questUndo.Clear();if(questHiddenMaster!=null){questHiddenMaster.SetActive(questHiddenMasterActive);questHiddenMaster=null;}System.IO.File.WriteAllText(System.IO.Path.Combine(root,"quest-restored.txt"),"Staged managed progress fields restored;no explicit award or dialogue advancement;original label refresh used");}
    void QuestCommand(string command){if(command=="ensure")NotebookEnsure();else if(command=="open")QuestPrepare();else if(command.StartsWith("scroll "))QuestScroll(command.Substring(7));else if(command=="readback")QuestReadback();else if(command=="headers")QuestHeaders();else if(command=="header-geometry")QuestHeaderGeometry();else if(command=="cases")QuestCases();else if(command=="title-cases")QuestTitleCases();else if(command.StartsWith("show "))QuestShow(command.Substring(5));else if(command=="geometry")QuestGeometry();else if(command=="diagnostics")QuestDiagnostics();else if(command=="hud")QuestHud();else if(command=="hud-empty")QuestHud(true);else if(command=="hud-geometry")QuestHudGeometry();else if(command=="restore")QuestRestore();else throw new System.Exception("Unknown Quest command");}
}
